// Editorial routing rules change explanation and verification tasks, never V3 scores.
import {startingPointBank as bank,startingOption,startingQuestions,text,preferredRegion,selections} from './starting-point.js';
import {escapeHTML as e} from '../explorer-views.js';
const tri=(en,zh,ms,locale)=>({en,'zh-CN':zh,ms})[locale]||en;
export const concernRoutes={
 A:{page:'ai',advice:['Compare sourced occupational tasks with AI assistance and the human review each task still needs. Test a task before making a major change.','先对照来源中的职业任务，区分 AI 辅助环节和仍需人工复核的部分，再用真实任务验证变化。','Bandingkan tugas pekerjaan bersumber dengan bantuan AI dan semakan manusia yang masih diperlukan. Uji tugas sebelum perubahan besar.']},
 B:{page:'compare',advice:['Compare one concrete work sample from each route. Record which tasks you want to repeat and which requirements still need testing.','比较两条路线的具体工作样本，记录你愿意反复做的任务，以及仍需验证的职业要求。','Bandingkan sampel kerja khusus daripada setiap laluan. Catat tugas yang mahu diulangi dan keperluan yang masih perlu diuji.']},
 C:{page:'tree',advice:['Use role requirements to choose a baseline exercise. Separate skills you report, requirements not yet tested and evidence you can produce next.','用职业要求选择一次基线练习，区分已自述的技能、尚未测量的要求和下一步可以补充的证据。','Gunakan keperluan pekerjaan untuk memilih latihan asas. Bezakan kemahiran dilaporkan, keperluan belum diuji dan bukti seterusnya.']},
 D:{page:'ai',advice:['Choose one occupational task, try AI within a defined workflow and independently verify the result. Tool usage alone is not proof of task quality.','选定一项职业任务，在明确流程中尝试 AI，并独立核查结果；使用过工具不等于交付质量已得到证明。','Pilih satu tugas pekerjaan, cuba AI dalam aliran kerja jelas dan sahkan hasil secara bebas. Penggunaan alat sahaja bukan bukti kualiti.']},
 E:{page:'plan',advice:['Turn a role-specific task into a work sample with a clear outcome, documented checks and external feedback; use it to test actual entry requirements.','把目标职业的一项任务做成可展示的样本，记录成果、核验和外部反馈，用它检查真实进入要求。','Jadikan tugas khusus pekerjaan sebagai sampel dengan hasil jelas, semakan didokumenkan dan maklum balas luar untuk menguji syarat kemasukan.']},
 F:{page:'compare',advice:['Identify requirements shared with your current field, then test one unfamiliar requirement before committing time or income to a transition.','先找与当前背景共有的职业要求，再验证一项陌生要求，之后再决定是否投入较大的时间或收入成本。','Kenal pasti keperluan yang dikongsi dengan bidang semasa, kemudian uji satu keperluan asing sebelum komitmen masa atau pendapatan.']},
 G:{page:'careers',advice:['Compare dated regional evidence and role requirements separately. Check language, recognised qualifications and employment eligibility rather than assuming skills guarantee access.','分别比较有日期的地区证据和职业要求，并核查语言、资格认可及就业资格，不能把技能直接等同于跨国准入。','Bandingkan bukti wilayah bertarikh dan keperluan pekerjaan secara berasingan. Semak bahasa, pengiktirafan kelayakan dan kelayakan bekerja.']},
 H:{page:'plan',advice:['Test a small AI-enabled application or service against a real user need. Keep evidence of usefulness and quality before treating it as a career opportunity.','围绕真实用户需求测试一个小型 AI 应用或服务，先保留有用性和质量证据，再判断是否值得发展为职业机会。','Uji aplikasi atau perkhidmatan kecil berasaskan AI terhadap keperluan pengguna sebenar. Simpan bukti kegunaan dan kualiti dahulu.']},
 I:{page:'map',advice:['Start with low-cost occupational task exploration and compare what you learn. A provisional direction is a trial, not a permanent choice.','先低成本体验职业任务，比较实际感受；暂选一个方向只是尝试，并非固定选择。','Mulakan penerokaan tugas pekerjaan berkos rendah dan bandingkan pembelajaran. Arah sementara ialah percubaan, bukan pilihan kekal.']}
};
export const objectivePages={A:'map',B:'ai',C:'tree',D:'plan',E:'compare',F:'careers',G:'plan',H:'map'};
export function startingPointContext(intake,locale='en'){
 if(!intake?.completed)return null;
 const a=intake.answers,route=concernRoutes[a.Q02.primary],secondary=selections(a.Q02).filter(id=>id!==a.Q02.primary).map(id=>concernRoutes[id]).filter(Boolean);
 const L=(en,zh,ms)=>tri(en,zh,ms,locale);
 const q5=bank.questions.find(q=>q.id==='Q05');
 const capabilities=q5.rows.map(row=>({id:row.id,label:text(row.label,locale),reported:a.Q05[row.id],labelReported:text(q5.options.find(o=>o.id===a.Q05[row.id]).label,locale),verified:false,status:a.Q05[row.id]==='untried'?'unmeasured':'self-reported',evidence:['Q05']}));
 const context={version:bank.version,stage:startingOption(intake,'Q01',locale),field:startingOption(intake,'Q04',locale),primaryConcern:startingOption(intake,'Q02',locale,'primary'),secondaryConcern:selections(a.Q02).filter(id=>id!==a.Q02.primary).map(id=>text(bank.questions.find(q=>q.id==='Q02').options.find(o=>o.id===id)?.label,locale)).join(' · '),impact:startingOption(intake,'Q03',locale),experience:startingOption(intake,'Q06',locale),objective:startingOption(intake,'Q08',locale),market:startingOption(intake,'Q09',locale),region:preferredRegion(intake),capabilities,barriers:a.Q07.map(id=>text(bank.questions.find(q=>q.id==='Q07').options.find(o=>o.id===id).label,locale)),circumstance:startingOption(intake,'Q10',locale),followup:startingOption(intake,'Q11',locale),focusPage:route.page,objectivePage:route.page,objectivePages:selections(a.Q08).map(id=>objectivePages[id]),focus:text({en:route.advice[0],'zh-CN':route.advice[1],ms:route.advice[2]},locale),secondaryFocus:secondary.map(route=>tri(...route.advice,locale)).join(' '),evidence:['Q01','Q02','Q03','Q04','Q05','Q06','Q07','Q08','Q09',...startingQuestions(a).filter(q=>['Q10','Q11'].includes(q.id)).map(q=>q.id)],storyShared:false};
 context.decisionPacing=['D','E'].includes(a.Q03)?L('You report an active or delayed decision. Prioritise one reversible evidence-gathering step before a consequential commitment. This is decision context, not a mental-health judgement.','你报告正在面临重要选择或暂缓行动。先完成一项可逆的证据收集任务，再作较大承诺；这是决策情境，不是心理状态判断。','Anda melaporkan keputusan aktif atau tertangguh. Utamakan satu langkah pengumpulan bukti yang boleh diubah sebelum komitmen besar. Ini konteks keputusan, bukan penilaian kesihatan mental.'):L('Use the exploration at your own pace. Collect task evidence before deciding whether a longer path is worth pursuing.','按自己的节奏探索，先积累任务证据，再决定是否长期投入。','Terokai mengikut rentak sendiri. Kumpulkan bukti tugas sebelum memilih laluan jangka panjang.');
 return context;
}
export function contextualPreparation(context,intake,path,locale='en'){
 const a=intake.answers,skill=path.requirements?.[0]||path.tasks?.[0]||path.title,L=(en,zh,ms)=>tri(en,zh,ms,locale);
 const beginner=path.reportedExperience?.evidence?.some(x=>typeof x.value==='number'&&x.value<4)||['guided','examples','untried'].includes(a.Q05.execution)||selections(a.Q06).some(id=>['A','B','G'].includes(id));
 const task=beginner?L(`For ${path.title}, begin with one guided example connected to “${skill}”. Then change one requirement and record what you could complete and check without help.`,`针对${path.title}，先参考一个与“${skill}”相关的有指导示例，再改变一项要求，记录哪些部分可以独立完成与核验。`,`Untuk ${path.title}, mulakan dengan satu contoh berpandu berkaitan “${skill}”. Kemudian ubah satu keperluan dan rekod bahagian yang boleh disiapkan serta disemak sendiri.`):L(`For ${path.title}, use an existing work sample to test “${skill}” against a new constraint. Keep an error log and request feedback on the role-specific quality checks.`,`针对${path.title}，用已有样本在新约束下检验“${skill}”，保留错误记录，并对该路线的验收标准征求反馈。`,`Untuk ${path.title}, gunakan sampel sedia ada untuk menguji “${skill}” dengan kekangan baharu. Simpan log ralat dan dapatkan maklum balas semakan kualiti khusus laluan.`);
 const check=a.Q05.problemSolving==='untried'?L('Problem solving was not yet attempted, so observe one debugging or error-analysis task rather than marking this capability absent.','问题解决选择了“尚未尝试”，因此先观察一次排错或错误分析任务，不将它当作能力缺失。','Penyelesaian masalah belum dicuba; perhatikan satu tugas analisis ralat dan jangan tandakannya sebagai kebolehan tiada.'):L('Compare the actual work and checks with your reported level; keep differences as evidence for the next review.','对照自述水平检查实际成果与核验记录，把不一致保留为下次复盘的证据。','Bandingkan kerja dan semakan sebenar dengan tahap dilaporkan; simpan perbezaan sebagai bukti semakan seterusnya.');
 return {task,check,evidence:['Q02','Q05','Q06','Q07','Q08'],requirement:skill};
}
export function renderStartingFocus(context,locale='en'){
 if(!context)return '';
 const L=(en,zh,ms)=>tri(en,zh,ms,locale);
 return `<section class="starting-report-focus"><span class="kicker">${L('YOUR DECISION, IN CONTEXT','围绕你需要解决的问题','KEPUTUSAN ANDA, DALAM KONTEKS')}</span><h2>${e(context.primaryConcern)}</h2><p>${e(context.focus)}</p><p><strong>${L('Your goal','你的目标','Matlamat anda')}:</strong> ${e(context.objective)}</p><p>${e(context.decisionPacing)}</p>${context.secondaryFocus?`<p><strong>${L('Also worth considering','同时关注','Juga perlu dipertimbangkan')}:</strong> ${e(context.secondaryFocus)}</p>`:''}${context.circumstance||context.followup?`<p>${e([context.circumstance,context.followup].filter(Boolean).join(' · '))}</p>`:''}<div class="ex-secondary-actions"><button class="button secondary" data-combined-action="page:${context.focusPage}">${L('Explore my main question','优先探索我的困惑','Terokai soalan utama saya')} ↗</button><button class="text-button" data-combined-action="page:${context.objectivePage}">${L('Work towards my goal','查看我的目标所需下一步','Usahakan matlamat saya')} ↗</button></div></section>`;
}
export function renderStartingCapabilities(context,locale='en'){
 if(!context)return '';
 const L=(en,zh,ms)=>tri(en,zh,ms,locale);
 return `<section class="starting-report-capabilities"><h2>${L('Your reported starting point','你自述的能力起点','Titik permulaan yang anda laporkan')}</h2><p>${e(context.stage)} · ${e(context.field)}</p><p>${e(context.experience)}</p><div class="starting-capabilities">${context.capabilities.map(row=>`<article><h3>${e(row.label)}</h3><strong>${e(row.labelReported)}</strong><p>${row.status==='unmeasured'?L('Not yet measured; no low ability is inferred.','尚未测量，不推断为低能力。','Belum diukur; tiada kebolehan rendah disimpulkan.'):L('Self-reported; a work sample and review are still needed.','仅为自述，仍需作品和复核证据。','Laporan kendiri; masih memerlukan sampel kerja dan semakan.')}</p></article>`).join('')}</div><p><strong>${L('Obstacles you identified','你感受到的障碍','Halangan yang anda kenal pasti')}:</strong> ${e(context.barriers.join(' · '))}</p><small>Q01 · Q04 · Q05 · Q06 · Q07</small></section>`;
}
export function personalAIContext(model,intake,shareStory=false){
 if(!intake?.completed)return model.p0.profile.map(c=>c.text).slice(0,8);
 const c=model.startingPointContext;
 const summary=[`Reported stage: ${c.stage}`,`Main concern: ${c.primaryConcern}`,`Goal: ${c.objective}`,`Reported experience: ${c.experience}`,`Perceived obstacles: ${c.barriers.join('; ')}`];
 const result=shareStory?[model.p0.profile[0]?.text||'No verified personal skills.',summary.join('. ').slice(0,400)]:[model.unified?.claims.find(c=>c.rule!=='decision-context')?.copy?.[{en:0,'zh-CN':1,ms:2}[model.p0.locale]??0]||model.p0.profile[0]?.text||'No verified skill evidence.',...summary];
 if(shareStory)for(let i=0;i<intake.story.length;i+=350)result.push('Unverified optional story: '+intake.story.slice(i,i+350));
 result.push('Self-reported capability snapshot: '+c.capabilities.map(row=>row.id+'='+row.reported).join('; '));
 return result.slice(0,8).map(s=>s.slice(0,400));
}
